import { NextResponse } from "next/server"
import { toTrustResult, validateTrustReport, type TrustReport } from "@/lib/trust-contract"
// Generated by the Trust Sprint toolkit (validation_harness.py --json) from a recorded run of
// scripts/trust-jaffle/ against the public jaffle-shop on Snowflake; never hand-edit.
import TRUST_SAMPLE from "@/lib/trust-sample.json"

// Reads no warehouse: the demo report is bundled, uploads are validated in memory.
export async function GET() {
  return NextResponse.json(toTrustResult(TRUST_SAMPLE as TrustReport, { demo: true }))
}

export async function POST(req: Request) {
  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ errors: ["body must be valid JSON"] }, { status: 400 })
  }
  const validation = validateTrustReport(body)
  if (!validation.ok || !validation.report) {
    return NextResponse.json({ errors: validation.errors }, { status: 400 })
  }
  return NextResponse.json(toTrustResult(validation.report, { demo: false }))
}
